00084         try {
00085             // Generate cryptographically secure random token
00086             $token = bin2hex(random_bytes(32));
00087         } catch (Exception $e) {
00088             Log::error('Failed to generate CSRF token: ' . $e->getMessage());
00089             // Fallback to less secure but functional method
